INSERT INTO products (id, title, slug, description, brand_id, category_id, variant_type, price, mrp, discount_percent, rating_avg, rating_count, thumbnail_url, warranty, shipping_info, return_policy, created_at, updated_at) VALUES
(1, 'Essence Mascara Lash Princess', 'essence-mascara-lash-princess', 'The Essence Mascara Lash Princess is a popular mascara known for its volumizing and lengthening effects. Achieve dramatic lashes with this long-lasting and cruelty-free formula.', 20, 25, 'NONE', 849, 949, 10, 3.5, 2, 'https://cdn.dummyjson.com/product-images/beauty/essence-mascara-lash-princess/thumbnail.webp', '1 week warranty', 'Ships in 3-5 business days', 'No return policy', '2026-05-09 06:12:00', '2026-05-09 06:12:00'),
(2, 'Eyeshadow Palette with Mirror', 'eyeshadow-palette-with-mirror', 'The Eyeshadow Palette with Mirror offers a versatile range of eyeshadow shades for creating stunning eye looks. With a built-in mirror, it''s convenient for on-the-go makeup application.', 34, 25, 'NONE', 1699, 2079, 18, 3.33, 3, 'https://cdn.dummyjson.com/product-images/beauty/eyeshadow-palette-with-mirror/thumbnail.webp', '1 year warranty', 'Ships in 2 weeks', '7 days return policy', '2026-09-14 06:31:00', '2026-09-14 06:31:00'),
(3, 'Powder Canister', 'powder-canister', 'The Powder Canister is a finely milled setting powder designed to set makeup and control shine. With a lightweight and translucent formula, it provides a smooth and matte finish.', 62, 25, 'NONE', 1269, 1409, 9, 3.33, 3, 'https://cdn.dummyjson.com/product-images/beauty/powder-canister/thumbnail.webp', '3 months warranty', 'Ships in 1-2 business days', 'No return policy', '2026-09-26 02:33:00', '2026-09-26 02:33:00'),
(4, 'Red Lipstick', 'red-lipstick', 'The Red Lipstick is a classic and bold choice for adding a pop of color to your lips. With a creamy and pigmented formula, it provides a vibrant and long-lasting finish.', 11, 25, 'NONE', 1099, 1249, 12, 4.67, 3, 'https://cdn.dummyjson.com/product-images/beauty/red-lipstick/thumbnail.webp', '3 year warranty', 'Ships in 1 week', '7 days return policy', '2026-05-05 10:04:00', '2026-05-05 10:04:00'),
(5, 'Red Nail Polish', 'red-nail-polish', 'The Red Nail Polish offers a rich and glossy red hue for vibrant and polished nails. With a quick-drying formula, it provides a salon-quality finish at home.', 44, 25, 'NONE', 759, 859, 11, 2.67, 3, 'https://cdn.dummyjson.com/product-images/beauty/red-nail-polish/thumbnail.webp', '1 month warranty', 'Ships overnight', 'No return policy', '2026-10-18 04:34:00', '2026-10-18 04:34:00'),
(6, 'Calvin Klein CK One', 'calvin-klein-ck-one', 'CK One by Calvin Klein is a classic unisex fragrance, known for its fresh and clean scent. It''s a versatile fragrance suitable for everyday wear.', 8, 26, 'NONE', 4249, 4329, 1, 3.0, 3, 'https://cdn.dummyjson.com/product-images/fragrances/calvin-klein-ck-one/thumbnail.webp', '1 week warranty', 'Ships overnight', '90 days return policy', '2026-09-23 06:51:00', '2026-09-23 06:51:00'),
(7, 'Chanel Coco Noir Eau De', 'chanel-coco-noir-eau-de', 'Coco Noir by Chanel is an elegant and mysterious fragrance, featuring notes of grapefruit, rose, and sandalwood. Perfect for evening occasions.', 10, 26, 'NONE', 10999, 13199, 16, 4.67, 3, 'https://cdn.dummyjson.com/product-images/fragrances/chanel-coco-noir-eau-de/thumbnail.webp', '3 year warranty', 'Ships overnight', 'No return policy', '2026-10-07 18:20:00', '2026-10-07 18:20:00'),
(8, 'Dior J''adore', 'dior-j-adore', 'J''adore by Dior is a luxurious and floral fragrance, known for its blend of ylang-ylang, rose, and jasmine. It embodies femininity and sophistication.', 16, 26, 'NONE', 7649, 8969, 14, 4.33, 3, 'https://cdn.dummyjson.com/product-images/fragrances/dior-j''adore/thumbnail.webp', '1 week warranty', 'Ships in 2 weeks', '7 days return policy', '2026-05-11 12:54:00', '2026-05-11 12:54:00'),
(9, 'Dolce Shine Eau de', 'dolce-shine-eau-de', 'Dolce Shine by Dolce & Gabbana is a vibrant and fruity fragrance, featuring notes of mango, jasmine, and blonde woods. It''s a joyful and youthful scent.', 18, 26, 'NONE', 5949, 5989, 0, 4.33, 3, 'https://cdn.dummyjson.com/product-images/fragrances/dolce-shine-eau-de/thumbnail.webp', '3 year warranty', 'Ships in 1 month', '7 days return policy', '2026-08-22 00:08:00', '2026-08-22 00:08:00'),
(10, 'Gucci Bloom Eau de', 'gucci-bloom-eau-de', 'Gucci Bloom by Gucci is a floral and captivating fragrance, with notes of tuberose, jasmine, and Rangoon creeper. It''s a modern and romantic scent.', 35, 26, 'NONE', 6799, 7939, 14, 3.33, 3, 'https://cdn.dummyjson.com/product-images/fragrances/gucci-bloom-eau-de/thumbnail.webp', '6 months warranty', 'Ships overnight', 'No return policy', '2026-05-09 21:33:00', '2026-05-09 21:33:00'),
(11, 'Annibale Colombo Bed', 'annibale-colombo-bed', 'The Annibale Colombo Bed is a luxurious and elegant bed frame, crafted with high-quality materials for a comfortable and stylish bedroom.', 2, 29, 'NONE', 161499, 176599, 8, 2.33, 3, 'https://cdn.dummyjson.com/product-images/furniture/annibale-colombo-bed/thumbnail.webp', '1 year warranty', 'Ships in 1 month', 'No return policy', '2026-04-27 11:53:00', '2026-04-27 11:53:00'),
(12, 'Annibale Colombo Sofa', 'annibale-colombo-sofa', 'The Annibale Colombo Sofa is a sophisticated and comfortable seating option, featuring exquisite design and premium upholstery for your living room.', 2, 29, 'NONE', 212499, 248199, 14, 3.0, 3, 'https://cdn.dummyjson.com/product-images/furniture/annibale-colombo-sofa/thumbnail.webp', 'Lifetime warranty', 'Ships in 1 week', '7 days return policy', '2026-06-22 21:03:00', '2026-06-22 21:03:00'),
(13, 'Bedside Table African Cherry', 'bedside-table-african-cherry', 'The Bedside Table in African Cherry is a stylish and functional addition to your bedroom, providing convenient storage space and a touch of elegance.', 30, 29, 'NONE', 25499, 31499, 19, 4.0, 3, 'https://cdn.dummyjson.com/product-images/furniture/bedside-table-african-cherry/thumbnail.webp', '5 year warranty', 'Ships overnight', '7 days return policy', '2026-08-22 08:55:00', '2026-08-22 08:55:00'),
(14, 'Knoll Saarinen Executive Conference Chair', 'knoll-saarinen-executive-conference-chair', 'The Knoll Saarinen Executive Conference Chair is a modern and ergonomic chair, perfect for your office or conference room with its timeless design.', 40, 29, 'NONE', 42499, 43399, 2, 3.0, 3, 'https://cdn.dummyjson.com/product-images/furniture/knoll-saarinen-executive-conference-chair/thumbnail.webp', '2 year warranty', 'Ships overnight', '60 days return policy', '2026-07-31 02:45:00', '2026-07-31 02:45:00'),
(15, 'Wooden Bathroom Sink With Mirror', 'wooden-bathroom-sink-with-mirror', 'The Wooden Bathroom Sink with Mirror is a unique and stylish addition to your bathroom, featuring a wooden sink countertop and a matching mirror.', 6, 29, 'NONE', 67999, 74599, 8, 4.0, 3, 'https://cdn.dummyjson.com/product-images/furniture/wooden-bathroom-sink-with-mirror/thumbnail.webp', '3 year warranty', 'Ships in 3-5 business days', '60 days return policy', '2026-08-16 14:51:00', '2026-08-16 14:51:00'),
